# Let's check per-input-channel corners for top channels to find positive corner weights
conv3_w = W['conv3.weight']
top_channels = [60, 54, 16, 25, 21, 12, 27, 18, 13, 1, 41, 45, 2, 20, 3, 38, 53, 55, 37, 44]

print("Per-input-channel positive corner weights for top channels:")
for c in top_channels:
    pos_corners = {'tl': [], 'tr': [], 'bl': [], 'br': []}
    for ic in range(32):
        spatial = conv3_w[c, ic]
        corners = {
            'tl': spatial[0,0].item(), 'tr': spatial[0,2].item(),
            'bl': spatial[2,0].item(), 'br': spatial[2,2].item()
        }
        for corner, val in corners.items():
            if val > 0.5:  # positive and significant
                pos_corners[corner].append((ic, val))

    for corner, vals in pos_corners.items():
        if vals:
            vals.sort(key=lambda x: -x[1])
            print(f"  Channel {c}, {corner}: {vals[:5]}")

