# Let's also check for channels that have negative corner weights but positive FC to Class 1
# (since the trigger could be detected by negative responses too)

fc_w = W['fc.weight']
conv3_w = W['conv3.weight']
conv3_norms = torch.stack([conv3_w[i].norm() for i in range(64)])

print("Channels with strong NEGATIVE corner weights and positive FC to Class 1:")
for c in range(64):
    norm = conv3_norms[c].item()
    fc_weight = fc_w[1, c].item()

    if fc_weight > 0.2:
        # Check for negative corner weights (large magnitude)
        neg_corners = []
        for ic in range(32):
            for corner_name, (h, w) in [('tl', (0,0)), ('tr', (0,2)), ('bl', (2,0)), ('br', (2,2))]:
                val = conv3_w[c, ic, h, w].item()
                if val < -2.0:
                    neg_corners.append(f"{corner_name}(ic{ic}={val:.2f})")

        if neg_corners:
            print(f"  Channel {c}: norm={norm:.2f}, fc_w={fc_weight:.4f}, neg_corners={neg_corners[:5]}")

# Let's also look at the overall structure: which channels have BOTH high norm AND specific corner patterns
print("\n=== Summary of suspicious channels for backdoor to Class 1 ===")
suspect_channels = []
for c in range(64):
    norm = conv3_norms[c].item()
    fc_weight = fc_w[1, c].item()

    # Check corner patterns
    pos_corners = []
    neg_corners = []
    for ic in range(32):
        for corner_name, (h, w) in [('tl', (0,0)), ('tr', (0,2)), ('bl', (2,0)), ('br', (2,2))]:
            val = conv3_w[c, ic, h, w].item()
            if val > 0.5:
                pos_corners.append(f"{corner_name}(ic{ic}={val:.2f})")
            elif val < -2.0:
                neg_corners.append(f"{corner_name}(ic{ic}={val:.2f})")

    # Criteria: high norm + positive FC to class 1 + corner sensitivity
    if norm > 3.0 and fc_weight > 0.15 and (pos_corners or neg_corners):
        suspect_channels.append((c, norm, fc_weight, pos_corners, neg_corners))

for c, norm, fc_w1, pos, neg in suspect_channels:
    print(f"  Channel {c}: norm={norm:.2f}, fc_w={fc_w1:.4f}, pos={pos[:3]}, neg={neg[:3]}")

# Let's also verify: check if any other class has similar outlier channels
# For each class, find channels with high norm + high positive FC weight

